// Fast path: extract doubles from a Python list
static int extract_doubles_list(PyObject *list, double *out, Py_ssize_t n) {
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *item = PyList_GET_ITEM(list, i);
        double val = PyFloat_AS_DOUBLE(item);
        if (val != val) { /* NaN check, shouldn't happen */ }
        out[i] = val;
    }
    return 0;
}

// Fast path: extract doubles from a numpy array
static int extract_doubles_numpy(PyObject *arr, double *out, Py_ssize_t n) {
    PyArrayObject *array = (PyArrayObject *)arr;
    if (PyArray_TYPE(array) == NPY_FLOAT64 && PyArray_IS_C_CONTIGUOUS(array)) {
        memcpy(out, PyArray_DATA(array), n * sizeof(double));
    } else {
        for (Py_ssize_t i = 0; i < n; i++) {
            out[i] = PyArray_GETITEM(array, (npy_intp)i);
        }
    }
    return 0;
