#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

static inline double py_double(PyObject *obj) {
    if (PyFloat_CheckExact(obj)) {
        return PyFloat_AS_DOUBLE(obj);
    }
    return PyFloat_AsDouble(obj);
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    Py_ssize_t n = PySequence_Length(weights_obj);
    if (n < 0) return NULL;

    double *w = (double *)malloc((size_t)n * sizeof(double));
    if (!w) { PyErr_NoMemory(); return NULL; }

    if (PyList_Check(weights_obj)) {
        for (Py_ssize_t i = 0; i < n; i++)
            w[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(weights_obj, i));
    } else {
        for (Py_ssize_t i = 0; i < n; i++) {
            PyObject *item = PySequence_GetItem(weights_obj, i);
            w[i] = py_double(item);
            Py_DECREF(item);
        }
    }

    double risk_squared = 0.0;

    if (PyList_Check(cov_obj)) {
        for (Py_ssize_t i = 0; i < n; i++) {
            PyObject *row = PyList_GET_ITEM(cov_obj, i);
            double row_sum = 0.0;
            for (Py_ssize_t j = 0; j < n; j++) {
                row_sum += PyFloat_AS_DOUBLE(PyList_GET_ITEM(row, j)) * w[j];
            }
            risk_squared += w[i] * row_sum;
        }
    } else {
        for (Py_ssize_t i = 0; i < n; i++) {
            PyObject *row = PySequence_GetItem(cov_obj, i);
            double row_sum = 0.0;
            for (Py_ssize_t j = 0; j < n; j++) {
                PyObject *item = PySequence_GetItem(row, j);
                row_sum += py_double(item) * w[j];
                Py_DECREF(item);
            }
            risk_squared += w[i] * row_sum;
            Py_DECREF(row);
        }
    }

    free(w);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    Py_ssize_t n = PySequence_Length(weights_obj);
    if (n < 0) return NULL;

    double total = 0.0;

    if (PyList_Check(weights_obj) && PyList_Check(returns_obj)) {
        for (Py_ssize_t i = 0; i < n; i++) {
            total += PyFloat_AS_DOUBLE(PyList_GET_ITEM(weights_obj, i)) *
                     PyFloat_AS_DOUBLE(PyList_GET_ITEM(returns_obj, i));
        }
    } else {
        for (Py_ssize_t i = 0; i < n; i++) {
            PyObject *wi = PySequence_GetItem(weights_obj, i);
            PyObject *ri = PySequence_GetItem(returns_obj, i);
            total += py_double(wi) * py_double(ri);
            Py_DECREF(wi);
            Py_DECREF(ri);
        }
    }

    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
